"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[1809],{6358(e){e.exports=JSON.parse('{"tag":{"label":"Case Study","permalink":"/concepts/tags/case-study","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"foundations-of-algorithms/case-study-pairwise","title":"Case Study - Pairwise Product","description":"To truly understand why algorithmics matters, it helps to experience failure first. In this case study we take a deceptively simple problem and solve it again and again. Each version fixes a problem of the previous one, and each fix teaches a different lesson: about the limits of data types, the cost of naive strategies, the impact of data representation, and the danger of \\"optimizations\\" that are not actually correct.","permalink":"/concepts/foundations-of-algorithms/case-study-pairwise"},{"id":"foundations-of-algorithms/searching-case-studies","title":"Searching Case Studies","description":"Searching is one of the most frequent operations in computing: looking up a user in a database, a word in a dictionary, a file in a directory, a value in a cache. In this final lesson of the chapter we apply everything we have learnt to three classic search algorithms. For each one we count instructions exactly, analyze the best, worst and average cases, express the result with asymptotic notation and connect it with real measurements.","permalink":"/concepts/foundations-of-algorithms/searching-case-studies"}],"unlisted":false}}')}}]);